    {"name": "edit", "arguments": {"path": "go_counting.py", "range": "2xv-39ke", "new": "class Board:\n    \"\"\"Count territories of each player in a Go game.\"\"\"\n\n    def __init__(self, board):\n        self.board = board\n        self.height = len(board)\n        self.width = len(board[0]) if self.height else 0\n\n    def territory(self, x, y):\n        if not (0 <= y < self.height and 0 <= x < self.width):\n            raise ValueError('Invalid coordinate')\n        if self.board[y][x] != ' ':\n            return '', set()\n        points = {(x, y)}\n        pending = [(x, y)]\n        borders = set()\n        while pending:\n            cx, cy = pending.pop()\n            for nx, ny in ((cx - 1, cy), (cx + 1, cy), (cx, cy - 1), (cx, cy + 1)):\n                if 0 <= ny < self.height and 0 <= nx < self.width:\n                    cell = self.board[ny][nx]\n                    if cell == ' ':\n                        if (nx, ny) not in points:\n                            points.add((nx, ny))\n                            pending.append((nx, ny))\n                    else:\n                        borders.add(cell)\n        owner = next(iter(borders)) if len(borders) == 1 else ''\n        return owner, points\n\n    def territories(self):\n        result = {'B': set(), 'W': set(), '': set()}\n        visited = set()\n        for y in range(self.height):\n            for x in range(self.width):\n                if self.board[y][x] == ' ' and (x, y) not in visited:\n                    owner, points = self.territory(x, y)\n                    result[owner].update(points)\n                    visited.update(points)\n        return result\n"}},
